import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"用户与邮箱管理","description":"","frontmatter":{},"headers":[],"relativePath":"admin/users-mailboxes.md","filePath":"admin/users-mailboxes.md","lastUpdated":1788621106000}`),a={name:`admin/users-mailboxes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="用户与邮箱管理" tabindex="-1">用户与邮箱管理 <a class="header-anchor" href="#用户与邮箱管理" aria-label="Permalink to “用户与邮箱管理”">​</a></h1><h2 id="用户" tabindex="-1">用户 <a class="header-anchor" href="#用户" aria-label="Permalink to “用户”">​</a></h2><p>用户列表支持查看账号状态、等级、配额、绑定信息和近期活动。管理员可以启用或禁用账号、调整授权范围、强制退出会话，以及在核验身份后重置两步验证。</p><p>禁用账号会阻止其继续使用服务，但不等同于立即删除数据。删除前应确认邮箱归属、组织角色、订单和工单等关联关系。</p><h2 id="邮箱" tabindex="-1">邮箱 <a class="header-anchor" href="#邮箱" aria-label="Permalink to “邮箱”">​</a></h2><p>邮箱管理页显示地址、域名、所有者、状态、容量和发信资格。常见操作包括：</p><ul><li>创建、停用或恢复邮箱。</li><li>调整显示顺序和容量限制。</li><li>查看共享关系、应用专用密码状态与活动记录。</li><li>转让邮箱或安排延迟清理。</li><li>对已进入清理流程的邮箱永久保留或彻底删除。</li></ul><p>邮箱转让后，原用户不应继续持有访问权限；检查共享成员和应用专用密码并按需撤销。</p><h2 id="邮件数据" tabindex="-1">邮件数据 <a class="header-anchor" href="#邮件数据" aria-label="Permalink to “邮件数据”">​</a></h2><p>管理员处理邮件问题时应遵守最小访问原则。优先根据邮件 ID、时间、投递状态和日志排查，只有在确有需要时才查看正文或附件。</p><h2 id="配额" tabindex="-1">配额 <a class="header-anchor" href="#配额" aria-label="Permalink to “配额”">​</a></h2><p>用户可用邮箱数、存储和发信额度可能同时受到账号等级、个人套餐和组织套餐影响。调整后若界面未变化，检查权益生效时间和缓存，再确认数据库中的实际配额来源。</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};